edits.old:
results = []
for item in iter:
    self.set_value(comp.target.id, item)
    results.append(self.visit(node.elt))
return tl_tuple(results)

edits.new:
results = []
for item in iter:
    self.set_value(comp.target.id, item)
    for condition in comp.ifs:
        predicate = self.visit(condition)
        if isinstance(predicate, language.constexpr):
            predicate = predicate.value
        if isinstance(predicate, language.tensor):
            raise ValueError("comprehension predicates must be compile-time values")
        if not predicate:
            break
    else:
        results.append(self.visit(node.elt))
return tl_tuple(results)
